const ACT_LBL_ = { weigh: 'שקילה', measure: 'היקפים', checkin: 'צ׳ק-אין שבועי', lift: 'אימון', steps: 'צעדים', food: 'יומן אוכל', habit: 'הרגל יומי', photo: 'תמונת התקדמות', mealphoto: 'צילום ארוחה', question: 'שאלה', blood: 'בדיקת דם', bloodvals: 'בדיקת דם', monthly: 'סיכום חודשי' };
function activityLog_(t, api, b) { if (!ACT_LBL_[api]) return; const name = appNameByToken_(t); if (!name) return; b = b || {};
  let det = ''; if (api === 'weigh' && b.kg) det = b.kg + ' ק״ג'; else if (api === 'food' && b.f) det = String(b.f).slice(0, 30) + (b.k ? ' · ' + b.k + ' קק״ל' : ''); else if (api === 'steps' && b.n) det = Number(b.n).toLocaleString('en') + ' צעדים'; else if (api === 'lift' && (b.ex || b.n)) det = String(b.ex || b.n).slice(0, 30) + (b.kg ? ' · ' + b.kg + ' ק״ג' : ''); else if (api === 'question' && b.q) det = String(b.q).slice(0, 40);
  const lock = LockService.getScriptLock(); try { lock.waitLock(3000); } catch (e) { return; }
  try { const P = PropertiesService.getScriptProperties(); let L = []; try { L = JSON.parse(P.getProperty('act_log') || '[]'); } catch (e) {}
    const now = Date.now(), last = L[L.length - 1]; if (last && last.n === name && last.a === api && now - last.at < 10 * 60000) { last.at = now; last.d = det || last.d; last.c = (last.c || 1) + 1; } else L.push({ at: now, n: name, a: api, d: det });
    P.setProperty('act_log', JSON.stringify(L.slice(-60))); } finally { lock.releaseLock(); } }
function dashboardActivity() { requireStaff(); let L = []; try { L = JSON.parse(PropertiesService.getScriptProperties().getProperty('act_log') || '[]'); } catch (e) {}
  return L.slice().reverse().map(x => ({ at: x.at, name: x.n, what: ACT_LBL_[x.a] || x.a, d: x.d || '', c: x.c || 1 })); }
